const profile = $input.first().json;

const keywords  = (profile.searchKeywords || ['Software Engineer']).slice(0, 2);
const locations = (profile.locations      || ['Bengaluru']).slice(0, 2);
const topSkills = (profile.skills         || []).slice(0, 2);

// Primary query: first keyword + first location
const primaryKeyword  = keywords[0]  || 'Software Engineer';
const primaryLocation = locations[0] || 'India';
const skillSuffix     = topSkills.join(' ');

// Naukri-friendly URL slug: 'Senior-Product-Manager-jobs-in-Bengaluru'
const toSlug = s => s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const naukriPath = `${toSlug(primaryKeyword)}-jobs-in-${toSlug(primaryLocation)}`;

// Glassdoor search URL
const gdQuery = encodeURIComponent(`${primaryKeyword} ${skillSuffix}`.trim());
const gdLocation = encodeURIComponent(primaryLocation);

return [{
  json: {
    profile,
    primaryKeyword,
    primaryLocation,
    skillSuffix,
    allKeywords:  keywords,
    allLocations: locations,
    naukriUrl:    `https://www.naukri.com/${naukriPath}`,
    glassdoorUrl: `https://www.glassdoor.co.in/Jobs/${toSlug(primaryLocation)}-${toSlug(primaryKeyword)}-jobs-SRCH_IL.0,${primaryLocation.length}_IC${Math.floor(Math.random()*9000+1000)}_KO${primaryLocation.length+1},${primaryLocation.length+1+primaryKeyword.length}.htm`,
    glassdoorSearchUrl: `https://www.glassdoor.co.in/Job/jobs.htm?suggestCount=0&typedKeyword=${gdQuery}&sc.keyword=${gdQuery}&locT=N&locId=115&jobType=all`
  }
}];

// Normalize jobs from Apify (LinkedIn), Firecrawl Naukri, Firecrawl Glassdoor
const allItems = $input.all();
const profile  = $('Build Queries').first().json.profile;
let rawJobs = [];

for (const item of allItems) {
  const d = item.json;

  // ── Apify LinkedIn response (array at root level)
  if (Array.isArray(d)) {
    for (const j of d) {
      rawJobs.push({
        title:   j.title       || j.jobTitle     || '',
        co:      j.companyName || j.company      || '',
        loc:     j.location    || j.place        || '',
        sal:     j.salary      || '',
        src:     'li',
        date:    j.publishedAt ? new Date(j.publishedAt).toLocaleDateString('en-IN', {day:'numeric',month:'short'}) : 'Recent',
        excerpt: (j.description || j.descriptionText || '').replace(/<[^>]+>/g,'').substring(0, 220),
        url:     j.jobUrl || j.url || '#'
      });
    }
    continue;
  }

  // ── Firecrawl extract response  { success, data: { extract: { jobs: [...] } } }
  const extracted = d?.data?.extract?.jobs || d?.extract?.jobs || d?.jobs || [];
  if (Array.isArray(extracted) && extracted.length) {
    const isGlassdoor = (d?.metadata?.url || d?.data?.metadata?.url || '').includes('glassdoor');
    for (const j of extracted) {
      if (!j.title) continue;
      rawJobs.push({
        title:   j.title       || '',
        co:      j.company     || '',
        loc:     j.location    || '',
        sal:     j.salary      || '',
        src:     isGlassdoor ? 'gd' : 'kn',
        date:    j.postedDate  || 'Recent',
        excerpt: (j.description || '').substring(0, 220),
        url:     j.url         || '#'
      });
    }
  }
}

// Deduplicate by title + company
const seen = new Set();
rawJobs = rawJobs.filter(j => {
  const key = `${j.title.toLowerCase().trim()}|${j.co.toLowerCase().trim()}`;
  if (seen.has(key)) return false;
  seen.add(key); return true;
});

console.log(`Collected ${rawJobs.length} raw jobs from all sources`);
return [{ json: { rawJobs, profile } }];

const { rawJobs, profile } = $input.first().json;

const skillWords     = (profile.skills          || []).map(s => s.toLowerCase()).filter(w => w.length > 2);
const titleKeywords  = (profile.searchKeywords  || []).map(k => k.toLowerCase());
const seniorityBoost = (profile.seniorityKeywords || []).map(w => w.toLowerCase());
const avoidWords     = (profile.avoidKeywords   || []).map(w => w.toLowerCase());
const expYears       = profile.yearsExperience  || 0;

const crossDomainPenalty = [
  'sales executive','business development','relationship manager','field sales',
  'telecaller','insurance advisor','loan officer','marketing executive',
  'hr executive','content writer','seo executive','accountant'
];
const overqualified  = ['intern','internship','trainee','apprentice','fresher','entry level','entry-level'];
const underqualified = ['vp ','vice president','chief ','director of','head of','managing director'];

const techDomains = ['software','engineering','frontend','backend','fullstack','devops',
  'data','ml','ai','product','design','analytics','cloud','mobile','security'];
const isTech = techDomains.some(d =>
  (profile.domain || '').toLowerCase().includes(d) ||
  skillWords.some(s => s.includes(d))
);

const scored = rawJobs.map(j => {
  const titleL  = (j.title || '').toLowerCase();
  const fullTxt = `${j.title} ${j.excerpt}`.toLowerCase();
  let score = 20;

  // Title keyword match
  let titleMatched = false;
  for (const kw of titleKeywords) {
    const kwWords = kw.split(/\s+/).filter(w => w.length > 2);
    const matched = kwWords.filter(w => titleL.includes(w));
    if (matched.length >= Math.ceil(kwWords.length * 0.6)) { score += 30; titleMatched = true; break; }
  }

  // Skill matches in full text
  let sm = 0;
  for (const s of skillWords) if (fullTxt.includes(s)) sm++;
  if (sm >= 1) score += Math.min(sm * 5, 25);

  // Seniority alignment bonus
  for (const w of seniorityBoost) if (titleL.includes(w)) { score += 8; break; }

  // Cross-domain penalty (non-tech jobs for tech profile)
  if (isTech) for (const w of crossDomainPenalty) if (titleL.includes(w)) { score -= 40; break; }

  // Seniority mismatch penalties
  if (expYears >= 4) for (const w of [...avoidWords, ...overqualified])  if (titleL.includes(w)) { score -= 25; break; }
  if (expYears <= 3) for (const w of underqualified) if (titleL.includes(w)) { score -= 15; break; }

  if (!titleMatched && sm === 0) score -= 25;

  return { ...j, match: Math.min(Math.max(score, 5), 99) };
});

const relevant = scored.filter(j => j.match >= 45);
const results  = (relevant.length >= 3 ? relevant : scored.filter(j => j.match >= 30))
  .sort((a, b) => b.match - a.match)
  .slice(0, 10)
  .map((j, i) => ({ ...j, id: i + 1 }));

console.log(`Returning ${results.length} scored jobs (from ${rawJobs.length} raw)`);
return [{ json: { jobs: results, profile } }];
